    def is_balanced(s):
        open_count = s.count('(')
        close_count = s.count(')')
        if open_count != close_count:
            return False
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return True

    str1, str2 = lst
    return 'Yes' if is_balanced(str1 + str2) or is_balanced(str2 + str1) else 'No'

